px;\n            border-radius: 10px;\n            cursor: pointer;\n            font-size: 16px;\n            margin: 20px 0 30px 0;\n            transition: transform 0.1s, box-shadow 0.2s;\n        }\n        \n        .predict-button:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 4px 8px rgba(255, 140, 0, 0.3);\n        }\n        \n        .predict-button:active {\n            transform: translateY(0);\n        }\n        \n        .results {\n            width: 100%;\n            max-width: 600px;\n            background-color: #2A2A2A;\n            border-radius: 15px;\n            padding: 20px;\n            display: none;\n        }\n        \n        .results h2 {\n            text-align: center;\n            margin-bottom: 20px;\n            background: linear-gradient(135deg, #FFCBA4, #FF8C00);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n        }\n        \n        .lottery-result {\n            margin-bottom: 20px;\n            border-bottom: 1px solid #444;\n            padding-bottom: 15px;\n        }\n        \n        .lottery-result:last-child {\n            border-bottom: none;\n        }\n        \n        .lottery-name {\n            font-weight: 700;\n            margin-bottom: 5px;\n            color: #FF8C00;\n        }\n        \n        .numbers {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 10px;\n            margin-top: 10px;\n        }\n        \n        .number {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            background: linear-gradient(135deg, #FFCBA4, #FF8C00);\n            font-weight: 700;\n        }\n        \n        .special-number {\n            background: linear-gradient(135deg, #FFD700, #FFA500);\n        }\n        \n        @media (max-width: 600px) {\n            .lottery-options {\n                grid-template-columns: 1fr;\n            }\n            \n            .number {\n                width: 35px;\n                height: 35px;\n                font-size: 14px;\n            }\n        }\n        \n        /* Calendar styles */\n        .calendar-container {\n            position: absolute;\n            top: 100%;\n            left: 0;\n            z-index: 10;\n            background-color: #1E1E1E;\n            border-radius: 10px;\n            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.5);\n            padding: 15px;\n            width: 100%;\n            display: none;\n        }\n        \n        .calendar-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 10px;\n        }\n        \n        .calendar-nav {\n            display: flex;\n            gap: 10px;\n        }\n        \n        .calendar-nav button {\n            background: none;\n            border: none;\n            color: white;\n            cursor: pointer;\n            font-size: 18px;\n        }\n        \n        .calendar-grid {\n            display: grid;\n            grid-template-columns: repeat(7, 1fr);\n            gap: 5px;\n        }\n        \n        .calendar-day-header {\n            text-align: center;\n            font-size: 12px;\n            color: #888;\n            font-weight: 700;\n            padding: 5px 0;\n        }\n        \n        .calendar-day {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            height: 35px;\n            border-radius: 5px;\n            cursor: pointer;\n        }\n        \n        .calendar-day:hover {\n            background-color: #333;\n        }\n        \n        .calendar-day.selected {\n            background: linear-gradient(135deg, #FFCBA4, #FF8C00);\n        }\n        \n        .calendar-day.other-month {\n            color: #555;\n        }\n        \n        .calendar-footer {\n            display: flex;\n            justify-content: flex-end;\n            margin-top: 10px;\n            gap: 10px;\n        }\n        \n        .calendar-footer button {\n            background: linear-gradient(135deg, #FFCBA4, #FF8C00);\n            border: none;\n            color: white;\n            font-weight: 500;\n            padding: 8px 15px;\n            border-radius: 5px;\n            cursor: pointer;\n        }\n        \n        .calendar-footer button.cancel {\n            background: #444;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"header\">\n        <h1>Numerology Lottery Predictor</h1>\n        <p>Get personalized lottery numbers based on numerology</p>\n    </div>\n    \n    <div class=\"input-container\">\n        <div class=\"input-field\">\n            <label for=\"fullName\">Your Full Name</label>\n            <input type=\"text\" id=\"fullName\" placeholder=\"Enter your full name\">\n        </div>\n        \n        <div class=\"input-field\">\n            <label for=\"birthdate\">Your Birth Date</label>\n            <input type=\"text\" id=\"birthdate\" placeholder=\"MM/DD/YYYY\" readonly>\n            <span class=\"calendar-icon\" onclick=\"toggleCalendar()\">📅</span>\n            \n            <!-- Calendar -->\n            <div class=\"calendar-container\" id=\"calendar\">\n                <div class=\"calendar-header\">\n                    <div id=\"currentMonth\">March 2025</div>\n                    <div class=\"calendar-nav\">\n                        <button onclick=\"prevMonth()\">&lt;</button>\n                        <button onclick=\"nextMonth()\">&gt;</button>\n                    </div>\n                </div>\n                <div class=\"calendar-grid\" id=\"calendarGrid\">\n                    <!-- Calendar days will be inserted here -->\n                </div>\n                <div class=\"calendar-footer\">\n                    <button class=\"cancel\" onclick=\"toggleCalendar()\">Cancel</button>\n                    <button onclick=\"selectDate()\">OK</button>\n                </div>\n            </div>\n        </div>\n        \n        <div class=\"lottery-select\">\n            <label>Select Lottery</label>\n            <div class=\"lottery-options\">\n                <!-- USA Lotteries -->\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'powerball\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"powerball\" value=\"powerball\">\n                    <span>Powerball (USA)</span>\n                </div>\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'megaMillions\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"megaMillions\" value=\"megaMillions\">\n                    <span>Mega Millions (USA)</span>\n                </div>\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'lotto649\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"lotto649\" value=\"lotto649\">\n                    <span>Lotto 649 (USA)</span>\n                </div>\n                \n                <!-- European Lotteries -->\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'euromillions\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"euromillions\" value=\"euromillions\">\n                    <span>EuroMillions (Europe)</span>\n                </div>\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'eurojackpot\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"eurojackpot\" value=\"eurojackpot\">\n                    <span>EuroJackpot (Europe)</span>\n                </div>\n                <div class=\"lottery-option\" onclick=\"selectLottery(this, \'ukLotto\')\">\n                    <input type=\"radio\" name=\"lottery\" id=\"ukLotto\" value=\"ukLotto\">\n                    <span>UK Lotto (Europe)</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    \n    <button class=\"predict-button\" onclick=\"predictNumbers()\">Generate Lucky Numbers</button>\n    \n    <div class=\"results\" id=\"results\">\n        <h2>Your Numerology Lottery Numbers</h2>\n        <div id=\"resultsContent\"></div>\n    </div>\n    \n    <script>\n        // Global variables\n        let selectedLottery = \'\';\n        let currentDate = new Date();\n        let selectedDate = null;\n        \n        // Lottery configurations\n        const lotteryConfigs = {\n            powerball: {\n                name: \"Powerball (USA)\",\n                mainNumbers: 5,\n                mainMax: 69,\n                specialNumbers: 1,\n                specialMax: 26\n            },\n            megaMillions: {\n                name: \"Mega Millions (USA)\",\n                mainNumbers: 5,\n                mainMax: 70,\n                specialNumbers: 1,\n                specialMax: 25\n            },\n            lotto649: {\n                name: \"Lotto 649 (USA)\",\n                mainNumbers: 6,\n                mainMax: 49,\n                specialNumbers: 0,\n                specialMax: 0\n            },\n            euromillions: {\n                name: \"EuroMillions (Europe)\",\n                mainNumbers: 5,\n                mainMax: 50,\n                specialNumbers: 2,\n                specialMax: 12\n            },\n            eurojackpot: {\n                name: \"EuroJackpot (Europe)\",\n                mainNumbers: 5,\n                mainMax: 50,\n                specialNumbers: 2,\n                specialMax: 10\n            },\n            ukLotto: {\n                name: \"UK Lotto (Europe)\",\n                mainNumbers: 6,\n                mainMax: 59,\n                specialNumbers: 0,\n                specialMax: 0\n            }\n        };\n        \n        // Select lottery function\n        function selectLottery(element, lotteryId) {\n            // Remove selected class from all options\n            const options = document.querySelectorAll(\'.lottery-option\');\n            options.forEach(option => option.classList.remove(\'selected\'));\n            \n            // Add selected class to clicked option\n            element.classList.add(\'selected\');\n            document.getElementById(lotteryId).checked = true;\n            selectedLottery = lotteryId;\n        }\n        \n        // Toggle calendar visibility\n        function toggleCalendar() {\n            const calendar = document.getElementById(\'calendar\');\n            if (calendar.style.display === \'block\') {\n                calendar.style.display = \'none\';\n            } else {\n                calendar.style.display = \'block\';\n                renderCalendar();\n            }\n        }\n        \n        // Render calendar\n        function renderCalendar() {\n            const month = currentDate.getMonth();\n            const year = currentDate.getFullYear();\n            \n            // Update header\n            const monthNames = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\",\n                \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"];\n            document.getElementById(\'currentMonth\').textContent = `\${monthNames[month]} \${year}`;\n            \n            // Clear calendar grid\n            const calendarGrid = document.getElementById(\'calendarGrid\');\n            calendarGrid.innerHTML = \'\';\n            \n            // Add day headers\n            const dayNames = [\"Su\", \"Mo\", \"Tu\", \"We\", \"Th\", \"Fr\", \"Sa\"];\n            dayNames.forEach(day => {\n                const dayHeader = document.createElement(\'div\');\n                dayHeader.className = \'calendar-day-header\';\n                dayHeader.textContent = day;\n                calendarGrid.appendChild(dayHeader);\n            });\n            \n            // Get first day of month and total days\n            const firstDay = new Date(year, month, 1).getDay();\n            const lastDate = new Date(year, month + 1, 0).getDate();\n            \n            // Add days from previous month\n            const prevMonthLastDate = new Date(year, month, 0).getDate();\n            for (let i = 0; i < firstDay; i++) {\n                const day = document.createElement(\'div\');\n                day.className = \'calendar-day other-month\';\n                day.textContent = prevMonthLastDate - firstDay + i + 1;\n                calendarGrid.appendChild(day);\n            }\n            \n            // Add days for current month\n            for (let i = 1; i <= lastDate; i++) {\n                const day = document.createElement(\'div\');\n                day.className = \'calendar-day\';\n                \n                // Check if this is the selected date\n                if (selectedDate && \n                    selectedDate.getDate() === i && \n                    selectedDate.getMonth() === month && \n                    selectedDate.getFullYear() === year) {\n                    day.classList.add(\'selected\');\n                }\n                \n                day.textContent = i;\n                day.onclick = function() {\n                    // Remove selected class from all days\n                    document.querySelectorAll(\'.calendar-day\').forEach(d => {\n                        d.classList.remove(\'selected\');\n                    });\n                    \n                    // Add selected class to this day\n                    day.classList.add(\'selected\');\n                    selectedDate = new Date(year, month, i);\n                };\n                calendarGrid.appendChild(day);\n            }\n            \n            // Add days from next month if needed\n            const totalCalendarCells = 42; // 6 rows of 7 days\n            const nextMonthDays = totalCalendarCells - (firstDay + lastDate);\n            for (let i = 1; i <= nextMonthDays; i++) {\n                const day = document.createElement(\'div\');\n                day.className = \'calendar-day other-month\';\n                day.textContent = i;\n                calendarGrid.appendChild(day);\n            }\n        }\n        \n        // Navigate to previous month\n        function prevMonth() {\n            currentDate.setMonth(currentDate.getMonth() - 1);\n            renderCalendar();\n        }\n        \n        // Navigate to next month\n        function nextMonth() {\n            currentDate.setMonth(currentDate.getMonth() + 1);\n            renderCalendar();\n        }\n        \n        // Select date and close calendar\n        function selectDate() {\n            if (selectedDate) {\n                const month = selectedDate.getMonth() + 1;\n                const day = selectedDate.getDate();\n                const year = selectedDate.getFullYear();\n                document.getElementById(\'birthdate\').value = \n                    `\${month < 10 ? \'0\' + month : month}/\${day < 10 ? \'0\' + day : day}/\${year}`;\n            }\n            toggleCalendar();\n        }\n        \n        // Generate random unique numbers\n        function generateUniqueNumbers(count, max) {\n            const numbers = new Set();\n            while (numbers.size < count) {\n                numbers.add(Math.floor(Math.random() * max) + 1);\n            }\n            return Array.from(numbers).sort((a, b) => a - b);\n        }\n        \n        // Calculate name number (numerology)\n        function calculateNameNumber(name) {\n            const charValues = {\n                \'a\': 1, \'b\': 2, \'c\': 3, \'d\': 4, \'e\': 5, \'f\': 6, \'g\': 7, \'h\': 8, \'i\': 9,\n                \'j\': 1, \'k\': 2, \'l\': 3, \'m\': 4, \'n\': 5, \'o\': 6, \'p\': 7, \'q\': 8, \'r\': 9,\n                \'s\': 1, \'t\': 2, \'u\': 3, \'v\': 4, \'w\': 5, \'x\': 6, \'y\': 7, \'z\': 8\n            };\n            \n            let total = 0;\n            name = name.toLowerCase().replace(/[^a-z]/g, \'\');\n            \n            for (let i = 0; i < name.length; i++) {\n                if (charValues[name[i]]) {\n                    total += charValues[name[i]];\n                }\n            }\n            \n            // Reduce to a single digit (except 11, 22, which are \"master numbers\")\n            while (total > 9 && total !== 11 && total !== 22) {\n                total = total.toString().split(\'\').reduce((sum, digit) => sum + parseInt(digit), 0);\n            }\n            \n            return total;\n        }\n        \n        // Calculate birthdate number (numerology)\n        function calculateBirthdateNumber(dateStr) {\n            if (!dateStr) return 0;\n            \n            const parts = dateStr.split(\'/\');\n            if (parts.length !== 3) return 0;\n            \n            const month = parseInt(parts[0]);\n            const day = parseInt(parts[1]);\n            const year = parseInt(parts[2]);\n            \n            let total = month + day + year;\n            \n            // Reduce to a single digit (except 11, 22, which are \"master numbers\")\n            while (total > 9 && total !== 11 && total !== 22) {\n                total = total.toString().split(\'\').reduce((sum, digit) => sum + parseInt(digit), 0);\n            }\n            \n            return total;\n        }\n        \n        // Predict lottery numbers\n        function predictNumbers() {\n            const name = document.getElementById(\'fullName\').value.trim();\n            const birthdate = document.getElementById(\'birthdate\').value.trim();\n            \n            if (!name) {\n                alert(\'Please enter your full name\');\n                return;\n            }\n            \n            if (!birthdate) {\n                alert(\'Please select your birth date\');\n                return;\n            }\n            \n            if (!selectedLottery) {\n                alert(\'Please select a lottery\');\n                return;\n            }\n            \n            const nameNumber = calculateNameNumber(name);\n            const birthdateNumber = calculateBirthdateNumber(birthdate);\n            const lotteryConfig = lotteryConfigs[selectedLottery];\n            \n            // Use numerology values to \"seed\" our random number generation\n            // (This is just for show - real numerology would be more complex)\n            const seed = nameNumber * birthdateNumber * new Date().getDate();\n            Math.seedrandom = function(seed) {\n                // Simple pseudo-random number generator with seed\n                let state = seed;\n                return function() {\n                    state = (state * 9301 + 49297) % 233280;\n                    return state / 233280;\n                };\n            };\n            \n            const random = Math.seedrandom(seed);\n            \n            // Generate main numbers\n            let mainNumbers = [];\n            while (mainNumbers.length < lotteryConfig.mainNumbers) {\n                const num = Math.floor(random() * lotteryConfig.mainMax) + 1;\n                if (!mainNumbers.includes(num)) {\n                    mainNumbers.push(num);\n                }\n            }\n            mainNumbers.sort((a, b) => a - b);\n            \n            // Generate special numbers\n            let specialNumbers = [];\n            while (specialNumbers.length < lotteryConfig.specialNumbers) {\n                const num = Math.floor(random() * lotteryConfig.specialMax) + 1;\n                if (!specialNumbers.includes(num)) {\n                    specialNumbers.push(num);\n                }\n            }\n            specialNumbers.sort((a, b) => a - b);\n            \n            // Display results\n            displayResults(lotteryConfig.name, mainNumbers, specialNumbers);\n            \n            // Generate additional lotteries for comparison\n            const resultsContent = document.getElementById(\'resultsContent\');\n            let additionalLotteries = Object.keys(lotteryConfigs)\n                .filter(key => key !== selectedLottery)\n                .slice(0, 2); // Get two more lotteries\n                \n            additionalLotteries.forEach(lotteryKey => {\n                const config = lotteryConfigs[lotteryKey];\n                \n                // Generate main numbers for this lottery\n                let addMainNums = [];\n                while (addMainNums.length < config.mainNumbers) {\n                    const num = Math.floor(random() * config.mainMax) + 1;\n                    if (!addMainNums.includes(num)) {\n                        addMainNums.push(num);\n                    }\n                }\n                addMainNums.sort((a, b) => a - b);\n                \n                // Generate special numbers for this lottery\n                let addSpecialNums = [];\n                while (addSpecialNums.length < config.specialNumbers) {\n                    const num = Math.floor(random() * config.specialMax) + 1;\n                    if (!addSpecialNums.includes(num)) {\n                        addSpecialNums.push(num);\n                    }\n                }\n                addSpecialNums.sort((a, b) => a - b);\n                \n                // Create HTML for this lottery\n                const lotteryDiv = document.createElement(\'div\');\n                lotteryDiv.className = \'lottery-result\';\n                \n                const nameDiv = document.createElement(\'div\');\n                nameDiv.className = \'lottery-name\';\n                nameDiv.textContent = config.name;\n                lotteryDiv.appendChild(nameDiv);\n                \n                const descDiv = document.createElement(\'div\');\n                descDiv.textContent = \'Your numerology prediction:\';\n                lotteryDiv.appendChild(descDiv);\n                \n                const numbersDiv = document.createElement(\'div\');\n                numbersDiv.className = \'numbers\';\n                \n                // Add main numbers\n                addMainNums.forEach(num => {\n                    const numDiv = document.createElement(\'div\');\n                    numDiv.className = \'number\';\n                    numDiv.textContent = num;\n                    numbersDiv.appendChild(numDiv);\n                });\n                \n                // Add special numbers if any\n                addSpecialNums.forEach(num => {\n                    const numDiv = document.createElement(\'div\');\n                    numDiv.className = \'number special-number\';\n                    numDiv.textContent = num;\n                    numbersDiv.appendChild(numDiv);\n                });\n                \n                lotteryDiv.appendChild(numbersDiv);\n                resultsContent.appendChild(lotteryDiv);\n            });\n            \n            // Show results container\n            document.getElementById(\'results\').style.display = \'block\';\n            // Scroll to results\n            document.getElementById(\'results\').scrollIntoView({ behavior: \'smooth\' });\n        }\n        \n        // Display results\n        function displayResults(lotteryName, mainNumbers, specialNumbers) {\n            const resultsContent = document.getElementById(\'resultsContent\');\n            resultsContent.innerHTML = \'\';\n            \n            const lotteryDiv = document.createElement(\'div\');\n            lotteryDiv.className = \'lottery-result\';\n            \n            const nameDiv = document.createElement(\'div\');\n            nameDiv.className = \'lottery-name\';\n            nameDiv.textContent = lotteryName + \" (Selected)\";\n            lotteryDiv.appendChild(nameDiv);\n            \n            const descDiv = document.createElement(\'div\');\n            descDiv.textContent = \'Your personalized numerology prediction:\';\n            lotteryDiv.appendChild(descDiv);\n            \n            const numbersDiv = document.createElement(\'div\');\n            numbersDiv.className = \'numbers\';\n            \n            // Add main numbers\n            mainNumbers.forEach(num => {\n                const numDiv = document.createElement(\'div\');\n                numDiv.className = \'number\';\n                numDiv.textContent = num;\n                numbersDiv.appendChild(numDiv);\n            });\n            \n            // Add special numbers if any\n            specialNumbers.forEach(num => {\n                const numDiv = document.createElement(\'div\');\n                numDiv.className = \'number special-number\';\n                numDiv.textContent = num;\n                numbersDiv.appendChild(numDiv);\n            });\n            \n            lotteryDiv.appendChild(numbersDiv);\n            resultsContent.appendChild(lotteryDiv);\n        }\n        \n        // Polyfill for Math.seedrandom if not available\n        Math.seedrandom = function(seed) {\n            // Simple pseudo-random number generator with seed\n            let state = seed;\n            return function() {\n                state = (state * 9301 + 49297) % 233280;\n                return state / 233280;\n            };\n        };\n        \n        // Initialize calendar on page load\n        document.addEventListener(\'DOMContentLoaded\', function() {\n            // Close calendar when clicking outside\n            document.addEventListener(\'click\', function(event) {\n                const calendar = document.getElementById(\'calendar\');\n                const birthdateField = document.getElementById(\'birthdate\');\n                const calendarIcon = document.querySelector(\'.calendar-icon\');\n                \n                if (calendar.style.display === \'block\' && \n                    !calendar.contains(event.target) && \n                    event.target !== birthdateField &&\n                    event.target !== calendarIcon) {\n                    calendar.style.display = \'none\';\n                }\n            });\n        });\n    </script>\n</body>\n</html>',
            height: 885.52,
